--- Makefile ---
CC ?= cc

CPPFLAGS := -Iinclude
CFLAGS := -std=c11 -Wall -Wextra -Werror -pedantic -pthread
LDFLAGS :=
LDLIBS :=

TARGET := bin/pbnfc
SOURCES := src/main.c src/diagnostics.c src/grammar_lexer.c src/grammar_ast.c src/markup_lexer.c src/chart.c src/worker_pool.c src/recognizer.c
OBJECTS := $(patsubst src/%.c,build/%.o,$(SOURCES))
DEPFILES := $(OBJECTS:.o=.d)
GRAMMAR_LEXER_SMOKE := build/grammar-lexer-core-smoke
GRAMMAR_AST_SMOKE := build/grammar-ast-core-smoke
MARKUP_LEXER_SMOKE := build/markup-lexer-core-smoke
CHART_CORE_SMOKE := build/chart-core-smoke
SEQUENTIAL_RECOGNIZER_SMOKE := build/sequential-recognizer-smoke
WORKER_POOL_CORE_SMOKE := build/worker-pool-core-smoke

.PHONY: all clean test-grammar-lexer-core test-grammar-ast-core test-markup-lexer-core test-chart-core test-worker-pool-core test-sequential-recognizer

all: $(TARGET)

test-grammar-lexer-core: $(GRAMMAR_LEXER_SMOKE)
	./$(GRAMMAR_LEXER_SMOKE)

test-grammar-ast-core: $(GRAMMAR_AST_SMOKE)
	./$(GRAMMAR_AST_SMOKE)

test-markup-lexer-core: $(MARKUP_LEXER_SMOKE)
	./$(MARKUP_LEXER_SMOKE)

test-chart-core: $(CHART_CORE_SMOKE)
	./$(CHART_CORE_SMOKE)

test-worker-pool-core: $(WORKER_POOL_CORE_SMOKE)
	./$(WORKER_POOL_CORE_SMOKE)

test-sequential-recognizer: $(SEQUENTIAL_RECOGNIZER_SMOKE)
	./$(SEQUENTIAL_RECOGNIZER_SMOKE)

$(GRAMMAR_LEXER_SMOKE): tests/grammar_lexer_smoke.c build/grammar_lexer.o build/diagnostics.o | build
	$(CC) $(CPPFLAGS) $(CFLAGS) -o $@ $^ $(LDLIBS)

$(GRAMMAR_AST_SMOKE): tests/grammar_ast_smoke.c build/grammar_ast.o build/grammar_lexer.o build/diagnostics.o | build
	$(CC) $(CPPFLAGS) $(CFLAGS) -o $@ $^ $(LDLIBS)

$(MARKUP_LEXER_SMOKE): tests/markup_lexer_smoke.c build/markup_lexer.o build/diagnostics.o | build
	$(CC) $(CPPFLAGS) $(CFLAGS) -o $@ $^ $(LDLIBS)

$(CHART_CORE_SMOKE): tests/chart_core_smoke.c build/chart.o | build
	$(CC) $(CPPFLAGS) $(CFLAGS) -o $@ $^ $(LDLIBS)

$(WORKER_POOL_CORE_SMOKE): tests/worker_pool_core_smoke.c build/worker_pool.o | build
	$(CC) $(CPPFLAGS) $(CFLAGS) -o $@ $^ $(LDLIBS)

$(SEQUENTIAL_RECOGNIZER_SMOKE): tests/sequential_recognizer_smoke.c build/recognizer.o build/chart.o build/grammar_ast.o build/grammar_lexer.o build/markup_lexer.o build/diagnostics.o | build
	$(CC) $(CPPFLAGS) $(CFLAGS) -o $@ $^ $(LDLIBS)

$(TARGET): $(OBJECTS) | bin
	$(CC) $(CFLAGS) $(LDFLAGS) -o $@ $^ $(LDLIBS)

build/%.o: src/%.c | build
	$(CC) $(CPPFLAGS) $(CFLAGS) -MMD -MP -c $< -o $@

bin build:
	mkdir -p $@

-include $(DEPFILES)

clean:
	rm -rf build bin
--- worker_pool.h ---
#ifndef PBNFC_WORKER_POOL_H
#define PBNFC_WORKER_POOL_H

#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>

#define PBNFC_WORKER_POOL_SIZE 8U

struct PbnfcWorkerPool;

typedef struct {
    struct PbnfcWorkerPool *pool;
    size_t worker_index;
} PbnfcWorkerPoolStart;

/*
 * A job is invoked exactly once by each persistent worker for every
 * pbnfc_worker_pool_run call.  worker_index is stable for the lifetime of
 * the pool and is in the range [0, PBNFC_WORKER_POOL_SIZE).
 */
typedef bool (*PbnfcWorkerPoolJob)(size_t worker_index, void *context);

typedef struct PbnfcWorkerPool {
    pthread_t threads[PBNFC_WORKER_POOL_SIZE];
    PbnfcWorkerPoolStart starts[PBNFC_WORKER_POOL_SIZE];
    pthread_mutex_t mutex;
    pthread_cond_t work_available;
    pthread_cond_t work_complete;
    PbnfcWorkerPoolJob job;
    void *job_context;
    size_t thread_count;
    size_t completed_count;
    unsigned long generation;
    unsigned long completed_generation;
    bool job_failed;
    bool running;
    bool shutdown_requested;
    bool shutdown_joining;
    bool synchronization_initialized;
} PbnfcWorkerPool;

/* Create exactly PBNFC_WORKER_POOL_SIZE persistent workers. */
bool pbnfc_worker_pool_init(PbnfcWorkerPool *pool);

/*
 * Run one generation and wait until every worker has completed its callback.
 * Only one generation may be active at a time.  A false callback result is
 * reported as false after all workers have still been allowed to finish.
 */
bool pbnfc_worker_pool_run(PbnfcWorkerPool *pool,
                           PbnfcWorkerPoolJob job,
                           void *context);

/* Stop and join all workers. Safe to call more than once. */
void pbnfc_worker_pool_shutdown(PbnfcWorkerPool *pool);

/* Release synchronization resources after shutdown. */
void pbnfc_worker_pool_free(PbnfcWorkerPool *pool);

size_t pbnfc_worker_pool_worker_count(const PbnfcWorkerPool *pool);

#endif
--- worker_pool.c ---
#include "worker_pool.h"

#include <string.h>

static void *worker_main(void *argument)
{
    PbnfcWorkerPoolStart *start = (PbnfcWorkerPoolStart *)argument;
    PbnfcWorkerPool *pool = start->pool;
    const size_t worker_index = start->worker_index;
    unsigned long observed_generation = 0UL;

    for (;;) {
        PbnfcWorkerPoolJob job;
        void *context;
        unsigned long job_generation;
        bool succeeded;

        (void)pthread_mutex_lock(&pool->mutex);
        while (!pool->shutdown_requested &&
               observed_generation == pool->generation) {
            (void)pthread_cond_wait(&pool->work_available, &pool->mutex);
        }
        if (pool->shutdown_requested) {
            (void)pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        observed_generation = pool->generation;
        job_generation = observed_generation;
        job = pool->job;
        context = pool->job_context;
        (void)pthread_mutex_unlock(&pool->mutex);

        succeeded = job(worker_index, context);

        (void)pthread_mutex_lock(&pool->mutex);
        /*
         * A run cannot be superseded before all callbacks return, but tie
         * completion to the observed epoch as an additional guard against a
         * stale worker completion being mistaken for the next generation.
         */
        if (job_generation == pool->generation) {
            if (!succeeded) {
                pool->job_failed = true;
            }
            ++pool->completed_count;
            if (pool->completed_count == pool->thread_count) {
                pool->completed_generation = job_generation;
                (void)pthread_cond_signal(&pool->work_complete);
            }
        }
        (void)pthread_mutex_unlock(&pool->mutex);
    }
}

bool pbnfc_worker_pool_init(PbnfcWorkerPool *pool)
{
    size_t index;
    int result;

    if (pool == NULL) {
        return false;
    }
    (void)memset(pool, 0, sizeof(*pool));
    result = pthread_mutex_init(&pool->mutex, NULL);
    if (result != 0) {
        return false;
    }
    result = pthread_cond_init(&pool->work_available, NULL);
    if (result != 0) {
        (void)pthread_mutex_destroy(&pool->mutex);
        return false;
    }
    result = pthread_cond_init(&pool->work_complete, NULL);
    if (result != 0) {
        (void)pthread_cond_destroy(&pool->work_available);
        (void)pthread_mutex_destroy(&pool->mutex);
        return false;
    }
    pool->synchronization_initialized = true;

    for (index = 0U; index < PBNFC_WORKER_POOL_SIZE; ++index) {
        pool->starts[index].pool = pool;
        pool->starts[index].worker_index = index;
        result = pthread_create(&pool->threads[index],
                                NULL,
                                worker_main,
                                &pool->starts[index]);
        if (result != 0) {
            pbnfc_worker_pool_shutdown(pool);
            pbnfc_worker_pool_free(pool);
            return false;
        }
        pool->thread_count = index + 1U;
    }
    return true;
}

bool pbnfc_worker_pool_run(PbnfcWorkerPool *pool,
                           PbnfcWorkerPoolJob job,
                           void *context)
{
    bool succeeded;

    if (pool == NULL || job == NULL || !pool->synchronization_initialized) {
        return false;
    }
    (void)pthread_mutex_lock(&pool->mutex);
    if (pool->shutdown_requested ||
        pool->thread_count != PBNFC_WORKER_POOL_SIZE || pool->running) {
        (void)pthread_mutex_unlock(&pool->mutex);
        return false;
    }
    pool->job = job;
    pool->job_context = context;
    pool->completed_count = 0U;
    pool->job_failed = false;
    pool->running = true;
    ++pool->generation;
    /* Publish the new epoch before waking workers. */
    pool->completed_generation = pool->generation - 1UL;
    (void)pthread_cond_broadcast(&pool->work_available);
    while (pool->completed_generation != pool->generation) {
        (void)pthread_cond_wait(&pool->work_complete, &pool->mutex);
    }
    succeeded = !pool->job_failed;
    pool->running = false;
    (void)pthread_mutex_unlock(&pool->mutex);
    return succeeded;
}

void pbnfc_worker_pool_shutdown(PbnfcWorkerPool *pool)
{
    size_t index;
    size_t thread_count;

    if (pool == NULL || !pool->synchronization_initialized) {
        return;
    }
    (void)pthread_mutex_lock(&pool->mutex);
    while (pool->shutdown_joining) {
        (void)pthread_cond_wait(&pool->work_complete, &pool->mutex);
    }
    if (pool->shutdown_requested && pool->thread_count == 0U) {
        (void)pthread_mutex_unlock(&pool->mutex);
        return;
    }

    pool->shutdown_requested = true;
    pool->shutdown_joining = true;
    (void)pthread_cond_broadcast(&pool->work_available);
    thread_count = pool->thread_count;
    (void)pthread_mutex_unlock(&pool->mutex);

    for (index = 0U; index < thread_count; ++index) {
        (void)pthread_join(pool->threads[index], NULL);
    }

    (void)pthread_mutex_lock(&pool->mutex);
    pool->thread_count = 0U;
    pool->shutdown_joining = false;
    (void)pthread_cond_broadcast(&pool->work_complete);
    (void)pthread_mutex_unlock(&pool->mutex);
}

void pbnfc_worker_pool_free(PbnfcWorkerPool *pool)
{
    if (pool == NULL || !pool->synchronization_initialized) {
        return;
    }
    pbnfc_worker_pool_shutdown(pool);
    (void)pthread_cond_destroy(&pool->work_complete);
    (void)pthread_cond_destroy(&pool->work_available);
    (void)pthread_mutex_destroy(&pool->mutex);
    (void)memset(pool, 0, sizeof(*pool));
}

size_t pbnfc_worker_pool_worker_count(const PbnfcWorkerPool *pool)
{
    if (pool == NULL || !pool->synchronization_initialized ||
        pool->shutdown_requested) {
        return 0U;
    }
    return pool->thread_count;
}
--- recognizer.h ---
#ifndef PBNFC_RECOGNIZER_H
#define PBNFC_RECOGNIZER_H

#include "grammar_ast.h"
#include "markup_lexer.h"

#include <stdbool.h>
#include <stddef.h>

typedef enum {
    PBNFC_RECOGNITION_ERROR = -1,
    PBNFC_RECOGNITION_REJECTED = 0,
    PBNFC_RECOGNITION_ACCEPTED = 1
} PbnfcRecognitionResult;

/*
 * Recognize one complete markup token stream with a validated grammar.
 * The token array excludes the lexer's EOF token and remains caller-owned.
 * When start_name is NULL, the grammar's %start rule is used.
 */
PbnfcRecognitionResult pbnfc_recognize_sequential(
    const PbnfcGrammar *grammar,
    const PbnfcMarkupToken *tokens,
    size_t token_count,
    const char *start_name);

/*
 * Recognize as above and emit one deterministic REJECT diagnostic when the
 * input is syntactically valid but does not match the grammar. The diagnostic
 * context is borrowed and may be NULL to suppress output.
 */
PbnfcRecognitionResult pbnfc_recognize_sequential_with_diagnostics(
    const PbnfcGrammar *grammar,
    const PbnfcMarkupToken *tokens,
    size_t token_count,
    const char *start_name,
    const PbnfcDiagnosticContext *diagnostics);

#endif
--- recognizer.c ---
#include "recognizer.h"

#include "chart.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static bool names_equal(const char *left, const char *right)
{
    return left != NULL && right != NULL && strcmp(left, right) == 0;
}

static bool production_index(const PbnfcGrammar *grammar,
                             const char *name,
                             size_t *index_out)
{
    size_t index;

    for (index = 0U; index < grammar->production_count; ++index) {
        if (names_equal(grammar->productions[index].name, name)) {
            if (index_out != NULL) {
                *index_out = index;
            }
            return true;
        }
    }
    return false;
}

static bool text_matches(const PbnfcGrammarSymbol *symbol,
                         const PbnfcMarkupToken *token)
{
    const char *kind_name;
    size_t name_length;

    if (symbol == NULL || token == NULL || symbol->name == NULL) {
        return false;
    }
    if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_TERMINAL) {
        name_length = strlen(symbol->name);
        return token->length == name_length &&
               (name_length == 0U ||
                memcmp(token->text, symbol->name, name_length) == 0);
    }
    if (symbol->kind != PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE) {
        return false;
    }
    kind_name = pbnfc_markup_token_kind_name(token->kind);
    return names_equal(symbol->name, kind_name);
}

static bool insert_item(PbnfcChart *chart,
                        size_t production,
                        size_t alternative,
                        size_t dot,
                        size_t origin,
                        size_t position)
{
    PbnfcChartItem item = pbnfc_chart_item_make(production,
                                                alternative,
                                                dot,
                                                origin,
                                                position);

    return pbnfc_chart_insert(chart, &item) != PBNFC_CHART_INSERT_ERROR;
}

static bool predict(PbnfcChart *chart,
                    const PbnfcGrammar *grammar,
                    const char *name,
                    size_t position)
{
    size_t production;
    size_t alternative;

    if (!production_index(grammar, name, &production)) {
        return false;
    }
    for (alternative = 0U;
         alternative < grammar->productions[production].alternative_count;
         ++alternative) {
        if (!insert_item(chart, production, alternative, 0U,
                         position, position)) {
            return false;
        }
    }
    return true;
}

static bool complete(PbnfcChart *chart,
                     const PbnfcGrammar *grammar,
                     const PbnfcChartItem *completed,
                     size_t position)
{
    const PbnfcGrammarProduction *completed_production;
    const PbnfcChartSet *origin_set;
    size_t source_index;
    size_t completed_production_index = completed->production;

    completed_production =
        &grammar->productions[completed_production_index];
    origin_set = pbnfc_chart_set_const(chart, completed->origin);
    if (origin_set == NULL) {
        return false;
    }

    /* The origin set can be the current set for an epsilon completion. */
    for (source_index = 0U;
         source_index < pbnfc_chart_set_size(origin_set);
         ++source_index) {
        PbnfcChartItem source_item = *pbnfc_chart_set_at(origin_set,
                                                         source_index);
        const PbnfcGrammarProduction *source_production =
            &grammar->productions[source_item.production];
        const PbnfcGrammarAlternative *source_alternative;
        const PbnfcGrammarSymbol *symbol;

        if (source_item.dot >= source_production->alternatives[
                                    source_item.alternative].symbol_count) {
            continue;
        }
        source_alternative =
            &source_production->alternatives[source_item.alternative];
        symbol = &source_alternative->symbols[source_item.dot];
        if (symbol->kind != PBNFC_GRAMMAR_SYMBOL_NONTERMINAL ||
            !names_equal(symbol->name, completed_production->name)) {
            continue;
        }
        if (!insert_item(chart,
                         source_item.production,
                         source_item.alternative,
                         source_item.dot + 1U,
                         source_item.origin,
                         position)) {
            return false;
        }
    }
    return true;
}

static bool close_position(PbnfcChart *chart,
                           const PbnfcGrammar *grammar,
                           size_t position)
{
    PbnfcChartSet *set = pbnfc_chart_set(chart, position);
    size_t item_index;

    if (set == NULL) {
        return false;
    }
    for (item_index = 0U;
         item_index < pbnfc_chart_set_size(set);
         ++item_index) {
        PbnfcChartItem item = *pbnfc_chart_set_at(set, item_index);
        const PbnfcGrammarProduction *production =
            &grammar->productions[item.production];
        const PbnfcGrammarAlternative *alternative =
            &production->alternatives[item.alternative];

        if (item.dot == alternative->symbol_count) {
            if (!complete(chart, grammar, &item, position)) {
                return false;
            }
        } else {
            const PbnfcGrammarSymbol *symbol =
                &alternative->symbols[item.dot];

            if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_NONTERMINAL &&
                !predict(chart, grammar, symbol->name, position)) {
                return false;
            }
        }
    }
    return true;
}

static bool scan_position(PbnfcChart *chart,
                          const PbnfcGrammar *grammar,
                          const PbnfcMarkupToken *tokens,
                          size_t token_count,
                          size_t position)
{
    const PbnfcChartSet *set;
    const PbnfcMarkupToken *token;
    size_t item_index;

    if (position >= token_count) {
        return true;
    }
    set = pbnfc_chart_set_const(chart, position);
    token = &tokens[position];
    if (set == NULL) {
        return false;
    }
    for (item_index = 0U;
         item_index < pbnfc_chart_set_size(set);
         ++item_index) {
        PbnfcChartItem item = *pbnfc_chart_set_at(set, item_index);
        const PbnfcGrammarProduction *production =
            &grammar->productions[item.production];
        const PbnfcGrammarAlternative *alternative =
            &production->alternatives[item.alternative];
        const PbnfcGrammarSymbol *symbol;

        if (item.dot >= alternative->symbol_count) {
            continue;
        }
        symbol = &alternative->symbols[item.dot];
        if ((symbol->kind == PBNFC_GRAMMAR_SYMBOL_TERMINAL ||
             symbol->kind == PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE) &&
            text_matches(symbol, token) &&
            !insert_item(chart,
                         item.production,
                         item.alternative,
                         item.dot + 1U,
                         item.origin,
                         position + 1U)) {
            return false;
        }
    }
    return true;
}

static bool has_accepting_item(const PbnfcChart *chart,
                               const PbnfcGrammar *grammar,
                               size_t start_production,
                               size_t final_position)
{
    const PbnfcChartSet *set =
        pbnfc_chart_set_const(chart, final_position);
    size_t item_index;

    if (set == NULL) {
        return false;
    }
    for (item_index = 0U;
         item_index < pbnfc_chart_set_size(set);
         ++item_index) {
        const PbnfcChartItem *item = pbnfc_chart_set_at(set, item_index);
        const PbnfcGrammarProduction *production;
        const PbnfcGrammarAlternative *alternative;

        if (item == NULL || item->production != start_production ||
            item->origin != 0U) {
            continue;
        }
        production = &grammar->productions[item->production];
        alternative = &production->alternatives[item->alternative];
        if (item->dot == alternative->symbol_count &&
            item->position == final_position) {
            return true;
        }
    }
    return false;
}

static bool append_expected_text(char **text,
                                 size_t *length,
                                 size_t *capacity,
                                 const char *addition)
{
    size_t addition_length;
    size_t needed;
    size_t next_capacity;
    char *next_text;

    if (text == NULL || length == NULL || capacity == NULL || addition == NULL) {
        return false;
    }
    addition_length = strlen(addition);
    if (*length > SIZE_MAX - addition_length - 1U) {
        return false;
    }
    needed = *length + addition_length + 1U;
    if (needed > *capacity) {
        next_capacity = *capacity == 0U ? 32U : *capacity;
        while (next_capacity < needed) {
            if (next_capacity > SIZE_MAX / 2U) {
                next_capacity = needed;
                break;
            }
            next_capacity *= 2U;
        }
        next_text = (char *)realloc(*text, next_capacity);
        if (next_text == NULL) {
            return false;
        }
        *text = next_text;
        *capacity = next_capacity;
    }
    (void)memcpy(*text + *length, addition, addition_length);
    *length += addition_length;
    (*text)[*length] = '\0';
    return true;
}

static bool expected_symbol_equal(const PbnfcGrammarSymbol *left,
                                  const PbnfcGrammarSymbol *right)
{
    return left != NULL && right != NULL && left->kind == right->kind &&
           names_equal(left->name, right->name);
}

static bool expected_symbol_seen(const PbnfcChartSet *set,
                                 size_t item_index,
                                 const PbnfcGrammar *grammar,
                                 const PbnfcGrammarSymbol *symbol)
{
    size_t prior_index;

    for (prior_index = 0U; prior_index < item_index; ++prior_index) {
        const PbnfcChartItem *prior_item =
            pbnfc_chart_set_at(set, prior_index);
        const PbnfcGrammarProduction *prior_production;
        const PbnfcGrammarAlternative *prior_alternative;
        const PbnfcGrammarSymbol *prior_symbol;

        if (prior_item == NULL) {
            continue;
        }
        prior_production = &grammar->productions[prior_item->production];
        prior_alternative =
            &prior_production->alternatives[prior_item->alternative];
        if (prior_item->dot >= prior_alternative->symbol_count) {
            continue;
        }
        prior_symbol = &prior_alternative->symbols[prior_item->dot];
        if (expected_symbol_equal(prior_symbol, symbol)) {
            return true;
        }
    }
    return false;
}

static bool append_expected_symbol(char **text,
                                   size_t *length,
                                   size_t *capacity,
                                   const PbnfcGrammarSymbol *symbol)
{
    const char *prefix = "";
    const char *suffix = "";

    if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_TERMINAL) {
        prefix = "'";
        suffix = "'";
    } else if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE) {
        prefix = "$";
    }
    return append_expected_text(text, length, capacity, prefix) &&
           append_expected_text(text, length, capacity, symbol->name) &&
           append_expected_text(text, length, capacity, suffix);
}

static char *expected_detail(const PbnfcChartSet *set,
                             const PbnfcGrammar *grammar)
{
    char *text = NULL;
    size_t length = 0U;
    size_t capacity = 0U;
    size_t item_index;

    if (set != NULL) {
        for (item_index = 0U;
             item_index < pbnfc_chart_set_size(set);
             ++item_index) {
            const PbnfcChartItem *item =
                pbnfc_chart_set_at(set, item_index);
            const PbnfcGrammarProduction *production;
            const PbnfcGrammarAlternative *alternative;
            const PbnfcGrammarSymbol *symbol;

            if (item == NULL) {
                continue;
            }
            production = &grammar->productions[item->production];
            alternative = &production->alternatives[item->alternative];
            if (item->dot >= alternative->symbol_count) {
                continue;
            }
            symbol = &alternative->symbols[item->dot];
            if (expected_symbol_seen(set, item_index, grammar, symbol)) {
                continue;
            }
            if (length != 0U &&
                !append_expected_text(&text, &length, &capacity, " | ")) {
                free(text);
                return NULL;
            }
            if (!append_expected_symbol(&text,
                                        &length,
                                        &capacity,
                                        symbol)) {
                free(text);
                return NULL;
            }
        }
    }
    if (length == 0U &&
        !append_expected_text(&text, &length, &capacity, "end of input")) {
        free(text);
        return NULL;
    }
    return text;
