--- sequential smoke ---
#include "grammar_ast.h"
#include "markup_lexer.h"
#include "recognizer.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int fail(const char *detail)
{
    (void)fprintf(stderr, "sequential recognizer smoke: %s\n", detail);
    return 1;
}

static PbnfcGrammar *parse_grammar(const char *source)
{
    PbnfcGrammar *grammar = NULL;

    if (!pbnfc_grammar_parse(source, strlen(source), NULL, &grammar) ||
        !pbnfc_grammar_validate(grammar, NULL)) {
        pbnfc_grammar_free(grammar);
        return NULL;
    }
    return grammar;
}

static bool lex_input(const char *source,
                      PbnfcMarkupToken **tokens_out,
                      size_t *count_out)
{
    PbnfcMarkupLexer lexer;
    PbnfcMarkupToken token;
    PbnfcMarkupToken *tokens = NULL;
    size_t count = 0U;
    size_t capacity = 0U;

    pbnfc_markup_lexer_init(&lexer, source, strlen(source), NULL);
    for (;;) {
        if (!pbnfc_markup_lexer_next(&lexer, &token)) {
            free(tokens);
            return false;
        }
        if (token.kind == PBNFC_MARKUP_TOKEN_EOF) {
            break;
        }
        if (count == capacity) {
            size_t next_capacity = capacity == 0U ? 8U : capacity * 2U;
            PbnfcMarkupToken *next_tokens =
                (PbnfcMarkupToken *)realloc(tokens,
                                             next_capacity * sizeof(*tokens));
            if (next_tokens == NULL) {
                free(tokens);
                return false;
            }
            tokens = next_tokens;
            capacity = next_capacity;
        }
        tokens[count] = token;
        ++count;
    }
    *tokens_out = tokens;
    *count_out = count;
    return true;
}

static int check_case(const PbnfcGrammar *grammar,
                      const char *source,
                      PbnfcRecognitionResult expected,
                      const char *detail)
{
    PbnfcMarkupToken *tokens = NULL;
    size_t token_count = 0U;
    PbnfcRecognitionResult actual;

    if (!lex_input(source, &tokens, &token_count)) {
        return fail("markup test input did not lex");
    }
    actual = pbnfc_recognize_sequential(grammar,
                                        tokens,
                                        token_count,
                                        NULL);
    free(tokens);
    if (actual != expected) {
        return fail(detail);
    }
    return 0;
}

static int check_rejection(const PbnfcGrammar *grammar,
                           const char *source,
                           const char *expected_diagnostic)
{
    PbnfcMarkupToken *tokens = NULL;
    size_t token_count = 0U;
    PbnfcDiagnosticContext diagnostics;
    PbnfcRecognitionResult actual;
    FILE *stream = tmpfile();
    char diagnostic[256];
    size_t length = 0U;
    int character;

    if (stream == NULL || !lex_input(source, &tokens, &token_count)) {
        if (stream != NULL) {
            (void)fclose(stream);
        }
        free(tokens);
        return fail("rejection input did not prepare");
    }
    pbnfc_diagnostic_context_init(&diagnostics, stream);
    actual = pbnfc_recognize_sequential_with_diagnostics(grammar,
                                                         tokens,
                                                         token_count,
                                                         NULL,
                                                         &diagnostics);
    free(tokens);
    if (actual != PBNFC_RECOGNITION_REJECTED) {
        (void)fclose(stream);
        return fail("rejection input was not rejected");
    }
    rewind(stream);
    while (length + 1U < sizeof(diagnostic) &&
           (character = fgetc(stream)) != EOF) {
        diagnostic[length] = (char)character;
        ++length;
    }
    diagnostic[length] = '\0';
    (void)fclose(stream);
    if (strcmp(diagnostic, expected_diagnostic) != 0) {
        return fail("rejection diagnostic was not deterministic or complete");
    }
    return 0;
}

int main(void)
{
    static const char nested_grammar[] =
        "%start Document\n"
        "%token TEXT\n"
        "Document ::= Nodes ;\n"
        "Nodes ::= Node Nodes | ;\n"
        "Node ::= Text | Group ;\n"
        "Text ::= $TEXT ;\n"
        "Group ::= '<' 'a' '>' Nodes '<' '/' 'a' '>' ;\n";
    static const char empty_grammar[] =
        "%start Empty\n"
        "Empty ::= ;\n";
    static const char rejection_grammar[] =
        "%start Document\n"
        "%token TEXT\n"
        "Document ::= '<' 'a' '>' $TEXT '<' '/' 'a' '>' ;\n";
    PbnfcGrammar *nested = parse_grammar(nested_grammar);
    PbnfcGrammar *empty = parse_grammar(empty_grammar);
    PbnfcGrammar *rejection = parse_grammar(rejection_grammar);

    if (nested == NULL || empty == NULL || rejection == NULL) {
        pbnfc_grammar_free(nested);
        pbnfc_grammar_free(empty);
        pbnfc_grammar_free(rejection);
        return fail("recognizer smoke grammar was rejected");
    }
    if (check_case(nested,
                   "<a>Hello<a>world</a></a>",
                   PBNFC_RECOGNITION_ACCEPTED,
                   "nested right-recursive input was rejected") != 0 ||
        check_case(nested,
                   "<a>Hello",
                   PBNFC_RECOGNITION_REJECTED,
                   "incomplete input was accepted") != 0 ||
        check_case(nested,
                   "<a>Hello</a><a>",
                   PBNFC_RECOGNITION_REJECTED,
                   "unconsumed input was accepted") != 0 ||
        check_case(empty,
                   "",
                   PBNFC_RECOGNITION_ACCEPTED,
                   "epsilon grammar did not accept empty input") != 0) {
        pbnfc_grammar_free(nested);
        pbnfc_grammar_free(empty);
        pbnfc_grammar_free(rejection);
        return 1;
    }
    if (check_rejection(rejection,
                        "<a>Hello</b>",
                        "REJECT offset=10 line=1 column=11 expected='a'\n") !=
            0 ||
        check_rejection(rejection,
                        "<a>Hello",
                        "REJECT offset=8 line=1 column=9 expected='<'\n") !=
            0) {
        pbnfc_grammar_free(nested);
        pbnfc_grammar_free(empty);
        pbnfc_grammar_free(rejection);
        return 1;
    }
    pbnfc_grammar_free(nested);
    pbnfc_grammar_free(empty);
    pbnfc_grammar_free(rejection);
    return 0;
}
--- main ---
#include "diagnostics.h"

#include <pthread.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    const char *grammar_path;
    const char *input_path;
    const char *start_name;
    bool have_grammar;
    bool have_input;
    bool have_start;
    bool have_stats;
} CliOptions;

static int command_line_error(const PbnfcDiagnosticContext *diagnostics,
                              const char *detail)
{
    (void)pbnfc_diagnostic_emit(diagnostics, detail, NULL);
    return 2;
}

static bool is_option(const char *argument)
{
    return argument[0] == '-' && argument[1] == '-';
}

static int parse_options(int argc,
                         char **argv,
                         CliOptions *options,
                         const PbnfcDiagnosticContext *diagnostics)
{
    int index;

    for (index = 1; index < argc; ++index) {
        const char *argument = argv[index];

        if (strcmp(argument, "--grammar") == 0) {
            if (options->have_grammar) {
                return command_line_error(diagnostics, "duplicate option --grammar");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --grammar");
            }
            options->grammar_path = argv[++index];
            options->have_grammar = true;
        } else if (strcmp(argument, "--input") == 0) {
            if (options->have_input) {
                return command_line_error(diagnostics, "duplicate option --input");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --input");
            }
            options->input_path = argv[++index];
            options->have_input = true;
        } else if (strcmp(argument, "--start") == 0) {
            if (options->have_start) {
                return command_line_error(diagnostics, "duplicate option --start");
            }
            if (index + 1 >= argc || is_option(argv[index + 1])) {
                return command_line_error(diagnostics, "missing value for --start");
            }
            options->start_name = argv[++index];
            options->have_start = true;
        } else if (strcmp(argument, "--stats") == 0) {
            if (options->have_stats) {
                return command_line_error(diagnostics, "duplicate option --stats");
            }
            options->have_stats = true;
        } else if (is_option(argument)) {
            return command_line_error(diagnostics, "unknown option");
        } else {
            return command_line_error(diagnostics, "unexpected positional argument");
        }
    }

    if (!options->have_grammar) {
        return command_line_error(diagnostics, "missing required option --grammar");
    }
    if (!options->have_input) {
        return command_line_error(diagnostics, "missing required option --input");
    }

    return 0;
}

int main(int argc, char **argv)
{
    CliOptions options = {0};
    PbnfcDiagnosticContext diagnostics;

    pbnfc_diagnostic_context_init(&diagnostics, stderr);

    (void)pthread_self();

    if (parse_options(argc, argv, &options, &diagnostics) != 0) {
        return 2;
    }

    (void)options;
    return command_line_error(&diagnostics, "grammar recognition is not implemented");
}
